import type {
  MedusaRequest,
  MedusaResponse,
} from "@medusajs/framework/http"
import { batchProductsWorkflow } from "@medusajs/medusa/core-flows"

export async function POST(
  req: MedusaRequest,
  res: MedusaResponse
) {
  const { result } = await batchProductsWorkflow(req.scope)
    .run({
      input: {
        create: [{
          title: "Shirt",
          options: [{
            title: "Color",
            values: ["Red", "Brown"]
          }],
          variants: [{
            title: "Red Shirt",
            options: {
              "Color": "Red"
            },
            prices: [{
              amount: 10,
              currency_code: "usd"
            }]
          }]
        }],
        update: [{
          id: "prod_123",
          title: "Pants"
        }],
        delete: ["prod_321"]
      }
    })

  res.send(result)
}

